from __future__ import absolute_import
import datetime
import logging
import os
import time

from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException, JavascriptException
from selenium.webdriver.common.keys import Keys
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.action_chains import ActionChains
from taf.selenium.core.common import PagePart
from taf.selenium.sbts.common.exceptions import FileExistsException
from taf.selenium.sbts.common.utils import choose_selector_way, wait_for_operation_success


class LocalBasicPage(PagePart):
    """
    Basic class, initializes web driver and provides common element operations functions.
    """

    def __init__(self, webdriver, download_checker=None, screenshot_dir=None):
        super(LocalBasicPage, self).__init__(webdriver)
        self._download_checker = download_checker
        self._default_screenshot_dir = screenshot_dir

    @property
    def download_checker(self):
        return self._download_checker

    @property
    def driver(self):
        return self._driver

    @property
    def download_dir(self):
        return self._download_checker.download_dir if self._download_checker else None

    @property
    def downloader(self):
        return self._download_checker.downloader if self._download_checker else None

    def switch_to_coam_login_tab(self):
        """
        There are three ways to open a new tab or window:
        1. use web driver to execute js script(will open a new window):
            driver.execute_script("window.open('your url','_blank');")
        2. send combination of keys COMMAND + T or CTRL + T to open a new tab on one window(can't work on firefox):
            ActionChains(driver).key_down(Keys.CONTROL).send_keys('t').key_up(Keys.CONTROL).perform()
        3. 1) send combination of keys COMMAND + T or CTRL + T to one element(can't work on firefox)
            driver.find_element_by_tag_name('body').send_keys(Keys.CONTROL + 't')
           2) send key CTRL and click one element to open a new tab:
            ActionChains(self.driver).key_down(Keys.CONTROL).click(element).key_up(Keys.CONTROL).perform()
        """
        link_xpath = "//a[contains(text(), 'Manual')]"
        current_window_handle = self.driver.current_window_handle
        ActionChains(self.driver).key_down(Keys.CONTROL). \
            click(self.driver.find_element_by_xpath(link_xpath)).key_up(Keys.CONTROL).perform()
        self.wait_for_new_window_open([current_window_handle])
        for handle in self.driver.window_handles:
            if handle != current_window_handle:
                self.driver.switch_to_window(handle)

    @wait_for_operation_success(2, FileExistsException, False, True)
    def save_screenshot(self, filename, screenshot_dir=None):
        screenshot_dir = screenshot_dir if screenshot_dir else self._default_screenshot_dir
        file_endswith_png = '{}_{}.png'.format(filename, datetime.datetime.now().strftime("%Y%m%d_%H%M%S"))
        file_path = '{}/{}'.format(screenshot_dir, file_endswith_png)
        self.driver.save_screenshot(file_path)
        time.sleep(1)
        saved_output = "screenshot {} saved under directory {}".format(file_endswith_png, screenshot_dir)
        if os.path.exists(file_path):
            logging.debug(saved_output)
        else:
            raise FileExistsException('no ' + saved_output)

    def download_files(self, start_time, download_timeout=1800):
        return self._download_checker.check(start_time, download_timeout)

    def disable_message_box(self, timeout=15):
        try:
            self._wait_for_element_by((By.CLASS_NAME, "notifyjs-corner"), timeout)
            self.hide_element("body > div[class=notifyjs-corner]")
        except TimeoutException:
            pass

    def get_fields_info_from_row(self, row_xpath, timeout):
        info_list = []
        self._wait_for_element_by((By.XPATH, row_xpath), timeout)
        for elem in self.driver.find_elements_by_xpath(row_xpath):
            info_list.append(elem.text.strip())
        return info_list

    def wait_until_element_is_clickable(self, xpath, timeout):
        try:
            self._until(EC.element_to_be_clickable((By.XPATH, xpath)), timeout)
        except TimeoutException:
            msg = 'Element with given xpath: {0} has not been able to click'.format(xpath)
            raise TimeoutException(msg)

    def wait_until_element_is_invisible(self, xpath, timeout):
        try:
            self._until(EC.invisibility_of_element_located((By.XPATH, xpath)), timeout)
        except TimeoutException:
            msg = 'Element with given xpath: {0} was not disappeared'.format(xpath)
            raise TimeoutException(msg)

    def click_enabled_element_after_visible(self, locator, timeout=60):
        self.wait_for_visibility(locator, timeout)
        self.click_enabled_element(locator, timeout)

    @choose_selector_way
    def display_element_in_sbts(self, select_element_script, *args, **kwargs):
        self._driver.execute_script(''.join([select_element_script, ".style.display='inline-block'"]))
        self._driver.execute_script(''.join([select_element_script, ".style.opacity=1"]))
        self._driver.execute_script(''.join([select_element_script, ".style.fontSize='5px'"]))

    @choose_selector_way
    def hide_element_in_sbts(self, select_element_script, *args, **kwargs):
        self._driver.execute_script(''.join([select_element_script, ".style=''"]))

    def load_file_from_hidden_button_in_sbts(self, button_location, button_xpath, file_path, timeout):
        """
        Actual load file button is hidden normally by developer, so we should show it , load file and then hide it

        :param button_location: str, hidden button unique location in web element
        :param button_xpath: str, hidden button's xpath
        :param file_path: str, load file's directory
        :param timeout: int, time to wait file loading

        :return:
        """
        self.display_element_in_sbts(button_location)
        self._wait_for_element_by((By.XPATH, button_xpath), timeout)
        elem = self._driver.find_element_by_xpath(button_xpath)
        self._driver.execute_script("arguments[0].scrollIntoView();", elem)
        elem.clear()
        elem.send_keys(file_path)
        try:
            self.hide_element_in_sbts(button_location)
        except JavascriptException:
            pass
        self._wait_for_element_by((By.XPATH, button_xpath), timeout)

    def wait_for_text_not_present_in_attribute(self, xpath, attr_name, text, timeout=60):
        self._until(lambda x: text not in self.get_attribute_by_xpath(xpath, attr_name, timeout), timeout)

    @wait_for_operation_success(3)
    def _scroll_elem_into_view(self, elem, block="center", inline="center", sleep=1):
        scroll_into_view = 'arguments[0].scrollIntoView({behavior: "smooth", block: "%s", inline: "%s"});' % (block,
                                                                                                              inline)
        self.driver.execute_script(scroll_into_view, elem)
        time.sleep(sleep)

    def get_attribute_by_xpath(self, xpath, attr_name, timeout=60):
        self._wait_for_element_by((By.XPATH, xpath), timeout)
        outcome = self._driver.find_element_by_xpath(xpath).get_attribute(attr_name)
        return outcome if outcome else ''

    def select_multi_checkbox(self,
                              selected_values,
                              expand_button_xpath,
                              select_all_checkbox_xpath,
                              filter_element_input_xpath,
                              element_xpath_template,
                              timeout=60):
        self.click_enabled_element((By.XPATH, expand_button_xpath), timeout)
        self.click_enabled_element((By.XPATH, select_all_checkbox_xpath), timeout)
        self.click_enabled_element((By.XPATH, select_all_checkbox_xpath), timeout)

        for elem_value in selected_values:
            self.clear_text_of_enabled_element((By.XPATH, filter_element_input_xpath), timeout)
            self.insert_text_to_enable_element((By.XPATH, filter_element_input_xpath), elem_value, timeout)
            self.click_enabled_element((By.XPATH, element_xpath_template.format(elem_value)), timeout)

        self.click_enabled_element((By.XPATH, expand_button_xpath), timeout)
